import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P01-Programming-thinking/23-Who-exactly-is-the-author-of-Dream-of-the-Red-Chamber.html","title":"23-《红楼梦》档案X：消失的作者与代码侦探","lang":"zh-CN","frontmatter":{"title":"23-《红楼梦》档案X：消失的作者与代码侦探","icon":"read","date":"2025-04-23T15:20:13.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1748754423000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":16,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":4}],"changelog":[{"hash":"ff4587c74d1c76d3aac787d3c96ea9dd9fecd743","time":1748754423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更改文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"74a53b0686aa1539ec2ea597d1eac819463bc35c","time":1745408262000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Implement code changes to enhance functionality and improve performance"},{"hash":"06b7a78a3653e13ab7127a0e87a0b63fdd188583","time":1745407702000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"4820feba0d252a4c73f5be1db84eb14686dbba65","time":1745406419000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Implement code changes to enhance functionality and improve performance"},{"hash":"18ddbc43bf71bb3410f07368f626a21e6772aee4","time":1745395762000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"初步完成"},{"hash":"af07943021cfb3125decea5ffbeee6321dabd9b2","time":1745393076000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"f14b0cca174ae138ce78063f95445916775cebdb","time":1718679320000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"e6ce4e085767c4f5b781fafab34fce9bb8a77757","time":1717922615000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"192.168.3.12"},{"hash":"698822ef18765f0a40a5fe8d17c8e37745f728e7","time":1717398270000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"2024-06-03 15:03:05"},{"hash":"772c411a931f42f9f56579305c16a96c1c834525","time":1675582584000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"e6a0f505dee0408ae039742ed8b7c873f3ccba3b","time":1675328574000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"添加 Python 教程"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":9.76,"words":2928},"filePathRelative":"column/Python-Programming-Course/P01-Programming-thinking/23-Who-exactly-is-the-author-of-Dream-of-the-Red-Chamber.md"}`),a={name:`23-Who-exactly-is-the-author-of-Dream-of-the-Red-Chamber.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<figure><img src="/assets/llll-CunaIKQZ.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>你相信“侦探”这个角色，也能由程序员来扮演吗？今天我们就来挑战一个大案子——谁才是真正写出《红楼梦》的人？</p><h2 id="_1-开场疑云-作者竟然不止一个" tabindex="-1"><a class="header-anchor" href="#_1-开场疑云-作者竟然不止一个"><span>1. 开场疑云：作者竟然不止一个？</span></a></h2><p>提起《红楼梦》，你也许会脱口而出：“曹雪芹！”没错，大部分语文课本上都是这么写的。但如果我告诉你，这个问题其实困扰了几代学者、甚至诞生出一个叫“红学”的专门学科呢？</p><p>200多年来，无数“红学家”像福尔摩斯一样，翻书页、找线索，甚至连鲁迅也加入过这场“文学破案”。有统计说，历史上曾有<strong>六十多个名字</strong>被怀疑是《红楼梦》的作者。你没听错，有人连皇帝都怀疑上了，什么崇祯啊、顺治啊，脑洞大的不得了。</p><p>为啥会搞成这样？因为线索太少了。你知道曹雪芹这个名字，可其实他活了多少年、长啥样、怎么写书的，史书上都说不清楚。所有关于他的资料，拼拼凑凑连一页纸都写不满。这种情况，当然给足了“侦探们”猜测的空间。</p><figure><img src="/assets/Hu_Shih_1960_color-DR6giQKD.jpg" alt="1960年的胡适" tabindex="0" loading="lazy"><figcaption>1960年的胡适</figcaption></figure><p>直到有一天，一位名叫<strong>胡适</strong>的大先生出场了。他提出一个广为流传的说法：《红楼梦》的<strong>前80回是曹雪芹写的，后40回是高鹗续的</strong>。听起来蛮合理的吧？但争议也从没停过——有人说全是曹写的，也有人说曹压根就不是作者。</p><p>可是，文学这种事，有什么绝对正确的意见呢？同样一篇文章，可能你觉得很美，但别的读者就不喜欢。</p><p>这就像是<strong>数学考试和语文考试的差别</strong>。</p><p>数学考试，你错了就是错了，看到考卷上最后的分数，你肯定是心服口服。但是语文就不一样了，凭什么他的作文得了满分，而我就要扣5分呢？我觉得自己的作文就该得满分呀——你是不是也这样想过呢？</p><p>对于红学家来说，也是这样。这又不是数学题，凭什么你说得就对，我说得就不对？所以，他们一直吵个不停，吵架吵得唾沫星子都能淹死人了。</p><p>那么，我们有什么办法劝劝架，让他们不再吵了呢？——用<strong>问题转换思想</strong>，把这个问题转化成数学题不就行了！</p><h2 id="_2-语文题-不-这是-数学题" tabindex="-1"><a class="header-anchor" href="#_2-语文题-不-这是-数学题"><span>2. 语文题？不，这是“数学题”！</span></a></h2><p>在大家吵来吵去，谁也说服不了谁，那怎么办？这时候，程序员上线了。他们说：“别吵了，这事可以用数学解决！”</p><p>比如我们以前学过的“密码分析”方法：在一门语言里，有的词使用次数高，有的词使用次数低，根据这个信息就能破解密码。</p><p>同样的，每个人写文章都有自己的语言习惯。就像你喜欢用“然后”、“其实”，我喜欢用“所以”、“比如”。这些词用得多了，就能体现“作者风格”。（省字版：<strong>文风和写作习惯</strong>）</p><p>早在70年前，一些好奇的研究者就用这招“解锁”《红楼梦》。（统计词汇的方法）</p><p>有位叫<strong>潘富俊</strong>的专家，原来是搞植物学的，他就分析《红楼梦》里植物出现的频率，结果发现：</p><ul><li>前80回：平均每回提到11种植物；</li><li>后40回：平均只提3.8种！</li></ul><p>这也太明显了吧？前80回的作者像个园艺大师，后40回的植物水平堪忧。显然，不像是同一个人写的。</p><p>你看，这种说法是不是很有道理呢？它至少说明了：《红楼梦》前后两部分的作者是不一样的。</p><p>可是这样，大家就会满足了吗？并没有。我们前边讲了，还是有很多人不服胡适。有没有可能，《红楼梦》的作者不止2个，而是有3个、4个？说不定，你的爷爷的爷爷的爷爷的爷爷，也掺和了一脚，写了一回呢？当然，这么说肯定是开玩笑的。但对于这种千古之谜，真要是胡适说什么我们就听什么，也不是个好主意。</p><p>那怎么办呢？程序员又想出来一个好办法，能够在事先没有任何信息的情况下，推测出来一本书有几个作者。这种办法就是咱们前边讲过的“<strong>聚类分析</strong>”。</p><h2 id="_3-程序员的秘密武器-聚类分析" tabindex="-1"><a class="header-anchor" href="#_3-程序员的秘密武器-聚类分析"><span>3. 程序员的秘密武器：聚类分析</span></a></h2><p>接下来，我们来讲一下更“高阶”一点的方法，在<strong>完全不知道作者是谁的前提下</strong>，就判断出这本书是不是出自多个作者之手。——叫<strong>聚类分析（Clustering）</strong>的算法。这个算法的核心思想是：“相似的归在一起”。</p><p>你可以这样理解：假如你看到一张地图，上面有120个小点，每个点代表一回《红楼梦》的文字风格。通过计算这些点之间的“相似程度”，程序就能自动把它们归为若干组。是不是太抽象，不够具体。别急，我们来看看下面具体的图示和例子。</p><figure><img src="/assets/sssllll-CPF3jySN.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>如果，我们假设每个小方块都代表一支军队，这些小方块就是几个国家的军队布置图。那现在我问你，一共有几个国家呢？</p><p>你肯定会猜3个吧？每个国家的军队一般都驻扎在自己国家的城市附近，它们肯定会凑成一团的。没错，按照小方块之间距离关系，聚类分析就把它们分成了<strong>3个阵营</strong>，分别用红黄蓝表示。这就是聚类分析的基本思想了！</p><figure><img src="/assets/wwwwwwww-LKqKt-wE.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>同样的，在做《红楼梦》作者分析的时候，程序员先是找出了一些能代表作者写作风格的文字。</p><p>然后通过一个算法，把每一回里有代表性的文字转换成小方块画在图上，最后看画出来的120个小方块里，哪些小方块凑在一起，那这些小方块代表的回数很可能就是同一个作者写的。</p><p>结果如何？</p><ol><li>程序发现：<strong>前80回和后40回确实不属于同一个“写作风格”群体</strong>，验证了胡适的说法；</li><li>更妙的是：<strong>第67回</strong>的风格有点“双重身份”，像是两个作者共同创作的；</li><li>而<strong>第105回</strong>则像是“外星人写的”，跟前面后面都不太一样！（也就是：即不像前80回的作者，也不像后40回的作者）</li></ol><p>聚类分析不光从数据上验证了《红楼梦》前后80回作者不同，而且还提出了另有新作者的观点，是不是很厉害呢！而且这种数据得出的结论让人信服。（用数据说话）</p><p>聚类分析算法都告诉我们：《红楼梦》作者这事，绝对没那么简单。</p><h2 id="_4-生活中也能-聚类分析" tabindex="-1"><a class="header-anchor" href="#_4-生活中也能-聚类分析"><span>4. 生活中也能“聚类分析”</span></a></h2><figure><img src="/assets/raw-20250423192846362-C1uBQZoK.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>你以为这种分析方式只能用在古文研究里？那可就小看它了。生活中，我们也常常不自觉地用“聚类思维”判断一个人。</p><p>比如说，班上来了一个插班生。大家肯定都在默默地观察他：他是个好玩的人吗，他会成为我的朋友吗？同样，老师也会关心：这个孩子学习成绩怎么样呀，能不能和其他同学好好相处？</p><p>可是，对于老师来说：现在距离考试还远着，成绩这事儿谁也说不准。那么，现在就完全没有办法了解他了吗？其实，利用聚类分析，就可以提前猜到这个新面孔的性格、学习成绩，甚至是一些小癖好。</p><p>具体怎么做呢？</p><p>我稍微提示一下，然后你再思考试一试：古人早就有一句话讲得明明白白：“<strong>物以类聚，人以群分</strong>。”（同类的东西经常聚在一起，而志同道合的人呢，也经常在一起活动。这就是中国古代的聚类思想。）——这就是聚类的朴素版本。</p><p>所以，我们具体的分析如下：</p><ol><li>插班生来到了一个陌生的环境，他肯定要交朋友。</li><li>而人类，就喜欢跟自己相似的人交朋友。</li><li>所以，只需等待一个星期，我们看看他跟谁成了朋友，就可以<strong>猜测他的个性和成绩</strong>了。</li></ol><p>比如：</p><ol><li><p>插班生跟班里最闹腾的几个人成了好朋友，那他基本上也是个活泼外向的人；</p></li><li><p>要是他跟学习成绩特别好的人成了朋友，那他的成绩大概也不会太差。</p></li><li><p>这其实就是在做“非官方聚类”：通过行为特征，猜测他属于哪个“人群类型”。</p></li></ol><p>当然了，这种聚类分析的方法虽然说不上100%准确，但要比毫无目的地瞎猜，还是要准确不少。</p><p><strong>小结</strong>：只要是需要分类的地方，就有聚类分析的用武之地。所以，用聚类分析给《红楼梦》的每一回按照作者分分类，那是再自然不过的了。</p><h2 id="_5-编程思维的神奇视角" tabindex="-1"><a class="header-anchor" href="#_5-编程思维的神奇视角"><span>5. 编程思维的神奇视角</span></a></h2><p>所以，别小看《红楼梦》作者之谜，它不仅是文学上的谜团，也是一道编程思维可以破解的逻辑题。我们学的算法，能从文本风格中看出作者是谁；从行为模式中分析人际关系。它能帮你破案、交朋友，甚至解决老师布置的“分析作文风格”的难题。</p><p>这就是聚类分析的魅力。</p><h2 id="_6-待选标题-不放入书稿" tabindex="-1"><a class="header-anchor" href="#_6-待选标题-不放入书稿"><span>6. 待选标题（不放入书稿）</span></a></h2><p>当然可以，来点更有创意、更吸睛的标题风格，以下是几种不同类型的灵感标题，供你挑选或激发灵感：</p><h3 id="_6-1-🎭-悬疑风格" tabindex="-1"><a class="header-anchor" href="#_6-1-🎭-悬疑风格"><span>6.1 🎭 悬疑风格</span></a></h3><ul><li><strong>《红楼梦》档案X：消失的作者与代码侦探</strong></li><li><strong>曹雪芹，还是AI写的？一场跨越两个世纪的文字追凶</strong></li><li><strong>梦中疑案：120回背后的“真凶”是谁？</strong></li></ul><h3 id="_6-2-🧠-科技x文学混搭风" tabindex="-1"><a class="header-anchor" href="#_6-2-🧠-科技x文学混搭风"><span>6.2 🧠 科技x文学混搭风</span></a></h3><ul><li><strong>当《红楼梦》遇上大数据：作者谜案破解指南</strong></li><li><strong>文本DNA检测：谁动了我的“红楼”？</strong></li><li><strong>文言文的指纹识别术：程序员也能破文学案</strong></li></ul><h3 id="_6-3-🎮-青少年风趣风" tabindex="-1"><a class="header-anchor" href="#_6-3-🎮-青少年风趣风"><span>6.3 🎮 青少年风趣风</span></a></h3><ul><li><strong>程序员探案笔记：谁偷写了《红楼梦》？</strong></li><li><strong>《红楼梦》也能 debug？是的，我们靠算法查出“幕后黑手”</strong></li><li><strong>写《红楼梦》的到底是谁？程序员用“点阵图”告诉你！</strong></li></ul><h3 id="_6-4-💡-知识型吸引风" tabindex="-1"><a class="header-anchor" href="#_6-4-💡-知识型吸引风"><span>6.4 💡 知识型吸引风</span></a></h3><ul><li><strong>从红学到算法：一场关于文学与数据的奇妙联动</strong></li><li><strong>程序员的红楼梦：用聚类分析解文学悬案</strong></li><li><strong>作者的影子藏在字里行间？用AI破译《红楼梦》的神秘密码</strong></li></ul><p>如果你希望标题再带点互动或反转风，也可以考虑这样的：</p><ul><li><strong>不是曹雪芹？那是谁写了《红楼梦》？聚类分析惊呆所有人</strong></li><li><strong>前80回是他，后40回是他，第67回呢？答案藏在算法里！</strong></li></ul>`,65)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};